**What this code covers**

- S.O.L.I.D. PRINCIPLES — 5 Rules for Clean, Maintainable Code
- S — Single Responsibility Principle (SRP)
- WHAT: A class should have only ONE reason to change.
- WHY: Each class does one thing well — easier to test and maintain.
- BAD — User class does TOO MANY things
- GOOD — Separate responsibilities
- O — Open/Closed Principle (OCP)
- WHAT: Open for EXTENSION, closed for MODIFICATION.

**Defines:** `UserBad`, `User`, `UserRepository`, `EmailService`, `ReportGenerator`, `DiscountBad`, `DiscountStrategy`, `RegularDiscount`, `PremiumDiscount`, `VIPDiscount`

```python name=design/solid_principles.py
# ============================================================
# S.O.L.I.D. PRINCIPLES — 5 Rules for Clean, Maintainable Code
# ============================================================

from abc import ABC, abstractmethod
from typing import Protocol

# ============================================================
# S — Single Responsibility Principle (SRP)
# ============================================================
# WHAT: A class should have only ONE reason to change.
# WHY:  Each class does one thing well — easier to test and maintain.

# BAD — User class does TOO MANY things
class UserBad:
    def __init__(self, name, email):
        self.name = name
        self.email = email

    def save_to_db(self): ...        # Database logic
    def send_email(self): ...        # Email logic
    def generate_report(self): ...   # Report logic

# GOOD — Separate responsibilities
class User:
    def __init__(self, name: str, email: str):
        self.name = name
        self.email = email

class UserRepository:
    def save(self, user: User): ...
    def find_by_email(self, email: str) -> User: ...

class EmailService:
    def send_welcome_email(self, user: User): ...

class ReportGenerator:
    def generate_user_report(self, user: User) -> str: ...

# ============================================================
# O — Open/Closed Principle (OCP)
# ============================================================
# WHAT: Open for EXTENSION, closed for MODIFICATION.
# WHY:  Add new features without changing existing code.

# BAD — Must modify calculate_discount for each new customer type
class DiscountBad:
    def calculate(self, customer_type, amount):
        if customer_type == "regular":
            return amount * 0.1
        elif customer_type == "premium":
            return amount * 0.2
        # Must ADD elif for each new type — modifying existing code!

# GOOD — Extend with new classes, never modify existing
class DiscountStrategy(ABC):
    @abstractmethod
    def calculate(self, amount: float) -> float: ...

class RegularDiscount(DiscountStrategy):
    def calculate(self, amount): return amount * 0.1

class PremiumDiscount(DiscountStrategy):
    def calculate(self, amount): return amount * 0.2

class VIPDiscount(DiscountStrategy):  # NEW — no existing code changed!
    def calculate(self, amount): return amount * 0.3

def apply_discount(strategy: DiscountStrategy, amount: float) -> float:
    return strategy.calculate(amount)

# ============================================================
# L — Liskov Substitution Principle (LSP)
# ============================================================
# WHAT: Subclasses must be substitutable for their base class
#        WITHOUT breaking the program.
# WHY:  Code that uses base class should work with any subclass.

# BAD — Square violates Rectangle's contract
class Rectangle:
    def __init__(self, width, height):
        self._width = width
        self._height = height

    @property
    def width(self): return self._width
    @width.setter
    def width(self, value): self._width = value

    @property
    def height(self): return self._height
    @height.setter
    def height(self, value): self._height = value

    def area(self): return self._width * self._height

class SquareBad(Rectangle):
    def __init__(self, side):
        super().__init__(side, side)

    @Rectangle.width.setter
    def width(self, value):
        self._width = self._height = value  # Changes both! Violates LSP!

# GOOD — Use composition or separate hierarchy
class Shape(ABC):
    @abstractmethod
    def area(self) -> float: ...

class GoodRectangle(Shape):
    def __init__(self, width, height):
        self.width, self.height = width, height
    def area(self): return self.width * self.height

class GoodSquare(Shape):
    def __init__(self, side):
        self.side = side
    def area(self): return self.side ** 2

# ============================================================
# I — Interface Segregation Principle (ISP)
# ============================================================
# WHAT: Don't force classes to implement interfaces they don't use.
# WHY:  Many specific interfaces > one fat interface.

# BAD — Worker forced to implement eat() for robots
class WorkerBad(ABC):
    @abstractmethod
    def work(self): ...
    @abstractmethod
    def eat(self): ...    # Robots don't eat!

# GOOD — Separate interfaces
class Workable(Protocol):
    def work(self) -> None: ...

class Eatable(Protocol):
    def eat(self) -> None: ...

class Human:
    def work(self): print("Working")
    def eat(self):  print("Eating")

class Robot:
    def work(self): print("Working 24/7")
    # No eat() — not needed!

def assign_work(worker: Workable):
    worker.work()  # Works with both Human and Robot

# ============================================================
# D — Dependency Inversion Principle (DIP)
# ============================================================
# WHAT: High-level modules should depend on ABSTRACTIONS,
#        not concrete implementations.
# WHY:  Easy to swap implementations (e.g., switch databases).

# BAD — Business logic depends on specific database
class OrderServiceBad:
    def __init__(self):
        self.db = MySQLDatabase()  # Tight coupling!

# GOOD — Depend on abstraction, inject dependency
class Database(Protocol):
    def save(self, data: dict) -> None: ...
    def find(self, query: dict) -> list: ...

class MySQLDatabase:
    def save(self, data): print(f"MySQL: saving {data}")
    def find(self, query): return []

class MongoDB:
    def save(self, data): print(f"MongoDB: saving {data}")
    def find(self, query): return []

class OrderService:
    def __init__(self, db: Database):  # Injected abstraction!
        self.db = db

    def create_order(self, order_data: dict):
        self.db.save(order_data)

# Easy to swap!
service_mysql = OrderService(MySQLDatabase())
service_mongo = OrderService(MongoDB())
```
